async function getProduct(productId) {
  const cacheKey = `product:${productId}`;

  // 1. Check Redis Cache
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached); // Cache Hit!

  // 2. Cache Miss: Query Database
  const product = await db.findProduct(productId);

  if (product) {
    // 3. Write to Redis with 10m TTL
    await redis.set(cacheKey, JSON.stringify(product), 'EX', 600);
  } else {
    // Prevent Cache Penetration: Cache null for 1m
    await redis.set(cacheKey, 'null', 'EX', 60);
  }

  return product;
}

async function fixedWindowRateLimit(ip) {
  const windowTime = Math.floor(Date.now() / 60000); // 1-minute window key
  const key = `ratelimit:${ip}:${windowTime}`;

  const requests = await redis.incr(key);
  if (requests === 1) {
    await redis.expire(key, 60); // Set 60s TTL on initial key creation
  }

  if (requests > 100) {
    return { allowed: false, remaining: 0 }; // Exceeded limit!
  }
  return { allowed: true, remaining: 100 - requests };
}

async function slidingWindowRateLimit(ip) {
  const key = `ratelimit:sliding:${ip}`;
  const now = Date.now();
  const windowMs = 60000; // 1-minute rolling window
  const clearBefore = now - windowMs;

  // 1. Remove timestamps older than rolling window
  await redis.zremrangebyscore(key, 0, clearBefore);

  // 2. Count requests in current rolling window
  const count = await redis.zcard(key);

  if (count >= 100) {
    return { allowed: false }; // Exceeded limit!
  }

  // 3. Add current timestamp to ZSET
  await redis.zadd(key, now, `${now}-${Math.random()}`);
  await redis.expire(key, 60);

  return { allowed: true };
}
